/* ---------------------- Utilidades ------------------------------------- */
const uid = (p) => `${p}_${Math.random().toString(36).slice(2, 8)}`;
const hoyISO = () => {
  // Fecha local Colombia (UTC-5), formato AAAA-MM-DD
  const now = new Date();
  const off = now.getTimezoneOffset(); // min
  const local = new Date(now.getTime() - (off + 300) * 60000 * 0); // se muestra tal cual
  return local.toISOString().slice(0, 10);
};
const periodoActual = () => hoyISO().slice(0, 7); // AAAA-MM
const fmtCOP = (n) => {
  const v = Math.round(Number(n) || 0);
  return "$" + v.toLocaleString("es-CO");
};
const nombreMes = (periodo) => {
  const [a, m] = periodo.split("-");
  const meses = ["ene", "feb", "mar", "abr", "may", "jun", "jul", "ago", "sep", "oct", "nov", "dic"];
  return `${meses[Number(m) - 1]}. ${a}`;
};
const MESES_LARGO = ["enero", "febrero", "marzo", "abril", "mayo", "junio", "julio", "agosto", "septiembre", "octubre", "noviembre", "diciembre"];
// Fecha AAAA-MM-DD → "27 de julio de 2026" (formato local Colombia)
const fmtFechaLarga = (iso) => {
  if (!iso) return "";
  const [a, m, d] = iso.split("-");
  return `${Number(d)} de ${MESES_LARGO[Number(m) - 1]} de ${a}`;
};
// Fecha AAAA-MM-DD → "27 jul" (compacta para listas)
const fmtFechaCorta = (iso) => {
  if (!iso) return "";
  const [, m, d] = iso.split("-");
  const meses = ["ene", "feb", "mar", "abr", "may", "jun", "jul", "ago", "sep", "oct", "nov", "dic"];
  return `${Number(d)} ${meses[Number(m) - 1]}`;
};
// Normaliza celular colombiano a formato internacional para wa.me (57 + 10 dígitos)
const telWa = (tel) => {
  if (!tel) return "";
  const limpio = String(tel).replace(/[^\d]/g, "");
  if (limpio.startsWith("57")) return limpio;
  return "57" + limpio;
};
// Lista de meses recientes (para filtros), del más nuevo al más viejo
const mesesRecientes = (n = 6) => {
  const out = [];
  const [a0, m0] = periodoActual().split("-").map(Number);
  let a = a0, m = m0;
  for (let i = 0; i < n; i++) {
    out.push(`${a}-${String(m).padStart(2, "0")}`);
    m -= 1;
    if (m === 0) { m = 12; a -= 1; }
  }
  return out;
};

/* ---------------------- Utilidades de calendario ----------------------- */
const DIAS_CORTO = ["dom", "lun", "mar", "mié", "jue", "vie", "sáb"];
const DIAS_LARGO = ["domingo", "lunes", "martes", "miércoles", "jueves", "viernes", "sábado"];
// Suma días a una fecha ISO y devuelve ISO
const sumarDias = (iso, n) => {
  const d = new Date(iso + "T12:00:00");
  d.setDate(d.getDate() + n);
  return d.toISOString().slice(0, 10);
};
// Día de la semana (0=dom … 6=sáb) de una fecha ISO
const diaSemana = (iso) => new Date(iso + "T12:00:00").getDay();
// Lunes de la semana que contiene la fecha ISO
const lunesDeSemana = (iso) => {
  const ds = diaSemana(iso);
  const resta = ds === 0 ? 6 : ds - 1; // lunes como inicio
  return sumarDias(iso, -resta);
};
// Los 7 días (ISO) de la semana que empieza en `lunesISO`
const semanaDesde = (lunesISO) => Array.from({ length: 7 }, (_, i) => sumarDias(lunesISO, i));
// "mié 30" para encabezado de día
const etiquetaDia = (iso) => `${DIAS_CORTO[diaSemana(iso)]} ${Number(iso.split("-")[2])}`;

/* ---------------------- Capa de almacenamiento ------------------------- */
const store = {
  async set(key, value) {
    localStorage.setItem(key, JSON.stringify(value));
    return true;
  },
  async get(key) {
    const r = localStorage.getItem(key);
    return r ? JSON.parse(r) : null;
  },
  async list(prefix) {
    return Object.keys(localStorage).filter((k) => k.startsWith(prefix));
  },
};

