/* ======================================================================= */
/*                              APP PRINCIPAL                              */
/* ======================================================================= */
export default function App() {
  const [tab, setTab] = useState("manada");
  const [cargando, setCargando] = useState(true);
  const [error, setError] = useState("");
  const [perroDetalleId, setPerroDetalleId] = useState(null); // vista de ficha (Fase 2)

  const [duenos, setDuenos] = useState([]);
  const [perros, setPerros] = useState([]);
  const [pagos, setPagos] = useState([]);
  const [paseos, setPaseos] = useState([]);

  /* -------- Carga inicial -------- */
  useEffect(() => {
    (async () => {
      try {
        const sembrado = await store.get("config:sembrado");
        if (!sembrado) {
          const ej = datosEjemplo();
          await Promise.all([
            ...ej.duenos.map((d) => store.set(`duenos:${d.id}`, d)),
            ...ej.perros.map((p) => store.set(`perros:${p.id}`, p)),
            ...ej.pagos.map((g) => store.set(`pagos:${g.periodo}:${g.id}`, g)),
            ...ej.paseos.map((w) => store.set(`paseos:${w.fecha}:${w.id}`, w)),
          ]);
          await store.set("config:sembrado", true);
        }
        await recargar();
      } catch (e) {
        setError("No pudimos cargar los datos. Intentá recargar la app.");
      } finally {
        setCargando(false);
      }
    })();
  }, []);

  const recargar = useCallback(async () => {
    try {
      const cargarPrefijo = async (prefijo) => {
        const keys = await store.list(prefijo);
        const items = await Promise.all(keys.map((k) => store.get(k)));
        return items.filter(Boolean);
      };
      const [ds, ps, gs, ws] = await Promise.all([
        cargarPrefijo("duenos:"),
        cargarPrefijo("perros:"),
        cargarPrefijo("pagos:"),
        cargarPrefijo("paseos:"),
      ]);
      setDuenos(ds);
      setPerros(ps);
      setPagos(gs);
      setPaseos(ws);
    } catch (e) {
      setError("Hubo un problema leyendo la información guardada.");
    }
  }, []);

  /* -------- Persistencia de entidades -------- */
  const guardarPerro = async (perro) => {
    const p = perro.id ? perro : { ...perro, id: uid("p") };
    await store.set(`perros:${p.id}`, p);
    await recargar();
  };
  const guardarDueno = async (dueno) => {
    const d = dueno.id ? dueno : { ...dueno, id: uid("d") };
    await store.set(`duenos:${d.id}`, d);
    await recargar();
  };
  const guardarPaseo = async (paseo) => {
    const w = paseo.id ? paseo : { ...paseo, id: uid("w") };
    await store.set(`paseos:${w.fecha}:${w.id}`, w);
    await recargar();
  };
  const guardarPago = async (pago) => {
    const g = pago.id ? pago : { ...pago, id: uid("pg") };
    await store.set(`pagos:${g.periodo}:${g.id}`, g);
    await recargar();
  };

  const ctx = {
    duenos, perros, pagos, paseos,
    guardarPerro, guardarDueno, guardarPaseo, guardarPago, recargar,
    abrirDetalle: (id) => setPerroDetalleId(id),
    cerrarDetalle: () => setPerroDetalleId(null),
  };

  if (cargando) {
    return (
      <Shell>
        <div style={{ ...S.centro, height: "80vh", flexDirection: "column", gap: 14 }}>
          <div style={S.spinner} />
          <div style={{ color: C.gris, fontSize: 15 }}>Cargando la manada…</div>
        </div>
        <Estilos />
      </Shell>
    );
  }

  return (
    <Shell>
      {error && (
        <div style={S.errorBanner}>
          {error}{" "}
          <button style={S.errorBtn} onClick={() => { setError(""); recargar(); }}>Reintentar</button>
        </div>
      )}

      <div style={{ paddingBottom: 88 }}>
        {tab === "manada" && <Manada ctx={ctx} />}
        {tab === "agenda" && <Agenda ctx={ctx} />}
        {tab === "paseos" && <Paseos ctx={ctx} />}
        {tab === "pagos" && <Pagos ctx={ctx} />}
        {tab === "resumen" && <Resumen ctx={ctx} />}
      </div>

      {perroDetalleId && (
        <DetallePerro ctx={ctx} perroId={perroDetalleId} onCerrar={() => setPerroDetalleId(null)} />
      )}

      <BarraPestanas tab={tab} setTab={setTab} />
      <Estilos />
    </Shell>
  );
}

/* ======================================================================= */
/*                                MANADA                                   */
/* ======================================================================= */
function Manada({ ctx }) {
  const { perros, duenos } = ctx;
  const [modal, setModal] = useState(null); // 'perro' | 'dueno' | null
  const [editPerro, setEditPerro] = useState(null);
  const [editDueno, setEditDueno] = useState(null);
  const [sub, setSub] = useState("perros"); // perros | duenos

  const activos = perros.filter((p) => p.activo !== false);

  return (
    <div>
      <Header titulo="La Manada" sub={`${activos.length} perros activos`} />

      <div style={S.segmento}>
        <button style={sub === "perros" ? S.segActivo : S.segItem} onClick={() => setSub("perros")}>Perros</button>
        <button style={sub === "duenos" ? S.segActivo : S.segItem} onClick={() => setSub("duenos")}>Dueños</button>
      </div>

      {sub === "perros" && (
        <>
          {activos.length === 0 && (
            <Vacio icono="🐾" titulo="Todavía no hay perros"
              texto="Registrá el primero para empezar a llevar el control de la manada." />
          )}
          {activos.map((p) => (
            <TarjetaPerro key={p.id} perro={p} dueno={duenos.find((d) => d.id === p.dueno_id)}
              onAbrir={() => ctx.abrirDetalle(p.id)} />
          ))}
          <button style={S.fabAncho} onClick={() => { setEditPerro(null); setModal("perro"); }}>
            + Registrar perro
          </button>
        </>
      )}

      {sub === "duenos" && (
        <>
          {duenos.filter((d) => d.activo !== false).length === 0 && (
            <Vacio icono="🏠" titulo="Aún no hay dueños"
              texto="Agregá a los vecinos para asociarlos con sus perros y sus planes." />
          )}
          {duenos.filter((d) => d.activo !== false).map((d) => (
            <TarjetaDueno key={d.id} dueno={d}
              perros={perros.filter((p) => p.dueno_id === d.id && p.activo !== false)}
              onEdit={() => { setEditDueno(d); setModal("dueno"); }} />
          ))}
          <button style={S.fabAncho} onClick={() => { setEditDueno(null); setModal("dueno"); }}>
            + Registrar dueño
          </button>
        </>
      )}

      {modal === "perro" && (
        <FormPerro ctx={ctx} inicial={editPerro} onCerrar={() => setModal(null)} />
      )}
      {modal === "dueno" && (
        <FormDueno ctx={ctx} inicial={editDueno} onCerrar={() => setModal(null)} />
      )}
    </div>
  );
}

function TarjetaPerro({ perro, dueno, onAbrir }) {
  const cme = esCME(perro.condicion);
  const cond = CONDICIONES.find((c) => c.c === perro.condicion);
  return (
    <button style={S.card} onClick={onAbrir}>
      <div style={{ display: "flex", gap: 12, alignItems: "center" }}>
        <div style={S.avatar}>{perro.emoji || "🐶"}</div>
        <div style={{ flex: 1, textAlign: "left", minWidth: 0 }}>
          <div style={{ display: "flex", alignItems: "center", gap: 8, flexWrap: "wrap" }}>
            <span style={S.cardTitulo}>{perro.nombre}</span>
            {cme && <span style={S.chipCME}>Solo individual</span>}
          </div>
          <div style={S.cardSub}>
            {perro.raza || "Sin raza"} · {TAMANOS.find((t) => t.c === perro.tamano)?.l || "—"}
          </div>
          <div style={S.cardMeta}>
            {dueno ? `${dueno.nombre} · ${perro.torre_apto || dueno.torre_apto || ""}` : "Sin dueño asignado"}
          </div>
        </div>
        <span style={{ color: C.gris, fontSize: 22, flexShrink: 0 }}>›</span>
      </div>
      <div style={S.tagsFila}>
        <Tag color={C.verde}>⚡ {ENERGIAS.find((e) => e.c === perro.energia)?.l || "—"}</Tag>
        <Tag color={C.terracota}>{TEMPERAMENTOS.find((t) => t.c === perro.temperamento)?.l || "—"}</Tag>
        {cond && perro.condicion !== "ninguna" && <Tag color={C.ambar}>{cond.l}</Tag>}
        {perro.vacunas_al_dia === false && <Tag color={C.rojo}>Vacunas pendientes</Tag>}
      </div>
    </button>
  );
}

function TarjetaDueno({ dueno, perros, onEdit }) {
  const plan = planPorCodigo(dueno.plan);
  return (
    <button style={S.card} onClick={onEdit}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", gap: 10 }}>
        <div style={{ textAlign: "left", flex: 1, minWidth: 0 }}>
          <div style={S.cardTitulo}>{dueno.nombre}</div>
          <div style={S.cardSub}>{dueno.torre_apto}</div>
          <div style={S.cardMeta}>📱 {dueno.telefono || "Sin teléfono"}</div>
        </div>
        {plan && (
          <div style={{ textAlign: "right" }}>
            <div style={{ fontWeight: 700, color: C.verde, fontSize: 15 }}>{fmtCOP(plan.tarifa)}</div>
            <div style={{ fontSize: 12, color: C.gris }}>{plan.l}</div>
          </div>
        )}
      </div>
      {perros.length > 0 && (
        <div style={S.tagsFila}>
          {perros.map((p) => <Tag key={p.id} color={C.cielo} dark>{p.emoji || "🐶"} {p.nombre}</Tag>)}
        </div>
      )}
    </button>
  );
}

/* ------------------------ Formulario Perro ----------------------------- */
function FormPerro({ ctx, inicial, onCerrar }) {
  const { duenos, guardarPerro, perros } = ctx;
  const [f, setF] = useState(inicial || {
    nombre: "", emoji: "🐶", dueno_id: "", raza: "", edad: "",
    tamano: "mediano", energia: "media", temperamento: "sociable",
    condicion: "ninguna", vacunas_al_dia: true, alergias: "", notas_salud: "",
    torre_apto: "", activo: true,
  });
  const [err, setErr] = useState({});
  const set = (k, v) => setF((s) => ({ ...s, [k]: v }));

  const cme = esCME(f.condicion);

  const validar = () => {
    const e = {};
    if (!f.nombre.trim()) e.nombre = "Poné el nombre del perro.";
    if (!f.dueno_id) e.dueno_id = "Elegí un dueño (registralo primero si falta).";
    setErr(e);
    return Object.keys(e).length === 0;
  };

  const guardar = async () => {
    if (!validar()) return;
    const dueno = duenos.find((d) => d.id === f.dueno_id);
    await guardarPerro({ ...f, torre_apto: f.torre_apto || dueno?.torre_apto || "" });
    onCerrar();
  };

  const eliminar = async () => {
    await guardarPerro({ ...f, activo: false });
    onCerrar();
  };

  const emojis = ["🐶", "🐕", "🦮", "🐩", "🐕‍🦺", "🐺"];

  return (
    <Modal titulo={inicial ? "Editar perro" : "Nuevo perro"} onCerrar={onCerrar}>
      <Campo label="Nombre" error={err.nombre} obligatorio>
        <input style={S.input} value={f.nombre} onChange={(e) => set("nombre", e.target.value)} placeholder="Ej: Rocco" />
      </Campo>

      <Campo label="Foto (emoji)">
        <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
          {emojis.map((em) => (
            <button key={em} onClick={() => set("emoji", em)}
              style={{ ...S.emojiBtn, ...(f.emoji === em ? S.emojiBtnOn : {}) }}>{em}</button>
          ))}
        </div>
      </Campo>

      <Campo label="Dueño" error={err.dueno_id} obligatorio>
        <select style={S.input} value={f.dueno_id} onChange={(e) => set("dueno_id", e.target.value)}>
          <option value="">Seleccioná…</option>
          {duenos.filter((d) => d.activo !== false).map((d) => (
            <option key={d.id} value={d.id}>{d.nombre} — {d.torre_apto}</option>
          ))}
        </select>
      </Campo>

      <Fila>
        <Campo label="Raza"><input style={S.input} value={f.raza} onChange={(e) => set("raza", e.target.value)} placeholder="Criolla" /></Campo>
        <Campo label="Edad"><input style={S.input} value={f.edad} onChange={(e) => set("edad", e.target.value)} placeholder="3 años" /></Campo>
      </Fila>

      <Campo label="Tamaño"><Segmentado ops={TAMANOS} valor={f.tamano} onChange={(v) => set("tamano", v)} /></Campo>
      <Campo label="Energía"><Segmentado ops={ENERGIAS} valor={f.energia} onChange={(v) => set("energia", v)} /></Campo>
      <Campo label="Temperamento"><Segmentado ops={TEMPERAMENTOS} valor={f.temperamento} onChange={(v) => set("temperamento", v)} /></Campo>
      <Campo label="Condición especial"><Segmentado ops={CONDICIONES} valor={f.condicion} onChange={(v) => set("condicion", v)} /></Campo>

      {cme && (
        <div style={S.avisoInfo}>
          🛡️ Este perro es de manejo especial: solo se puede agendar en <b>paseos individuales</b>.
        </div>
      )}

      <Campo label="¿Vacunas al día?">
        <div style={{ display: "flex", gap: 8 }}>
          <button style={{ ...S.toggle, ...(f.vacunas_al_dia ? S.toggleOn : {}) }} onClick={() => set("vacunas_al_dia", true)}>Sí</button>
          <button style={{ ...S.toggle, ...(!f.vacunas_al_dia ? S.toggleOnRojo : {}) }} onClick={() => set("vacunas_al_dia", false)}>No</button>
        </div>
      </Campo>

      <Campo label="Alergias"><input style={S.input} value={f.alergias} onChange={(e) => set("alergias", e.target.value)} placeholder="Ninguna" /></Campo>
      <Campo label="Notas médicas / de manejo">
        <textarea style={{ ...S.input, minHeight: 70, resize: "vertical" }} value={f.notas_salud} onChange={(e) => set("notas_salud", e.target.value)} placeholder="Medicación, cuidados…" />
      </Campo>

      <button style={S.btnPrimario} onClick={guardar}>{inicial ? "Guardar cambios" : "Registrar perro"}</button>
      {inicial && <button style={S.btnEliminar} onClick={eliminar}>Dar de baja</button>}
    </Modal>
  );
}

/* ------------------------ Formulario Dueño ----------------------------- */
function FormDueno({ ctx, inicial, onCerrar }) {
  const { guardarDueno } = ctx;
  const [f, setF] = useState(inicial || {
    nombre: "", torre_apto: "", telefono: "", plan: "grupal_3x", activo: true,
  });
  const [err, setErr] = useState({});
  const set = (k, v) => setF((s) => ({ ...s, [k]: v }));
  const plan = planPorCodigo(f.plan);

  const validar = () => {
    const e = {};
    if (!f.nombre.trim()) e.nombre = "Poné el nombre del dueño.";
    if (!f.torre_apto.trim()) e.torre_apto = "Indicá torre y apartamento.";
    setErr(e);
    return Object.keys(e).length === 0;
  };
  const guardar = async () => {
    if (!validar()) return;
    await guardarDueno(f);
    onCerrar();
  };
  const eliminar = async () => { await guardarDueno({ ...f, activo: false }); onCerrar(); };

  return (
    <Modal titulo={inicial ? "Editar dueño" : "Nuevo dueño"} onCerrar={onCerrar}>
      <Campo label="Nombre" error={err.nombre} obligatorio>
        <input style={S.input} value={f.nombre} onChange={(e) => set("nombre", e.target.value)} placeholder="Ej: Laura Restrepo" />
      </Campo>
      <Campo label="Torre y apartamento" error={err.torre_apto} obligatorio>
        <input style={S.input} value={f.torre_apto} onChange={(e) => set("torre_apto", e.target.value)} placeholder="Torre 3 · Apto 502" />
      </Campo>
      <Campo label="Teléfono (WhatsApp)">
        <input style={S.input} inputMode="numeric" value={f.telefono} onChange={(e) => set("telefono", e.target.value.replace(/[^\d]/g, ""))} placeholder="3001234567" />
      </Campo>
      <Campo label="Plan contratado">
        <select style={S.input} value={f.plan} onChange={(e) => set("plan", e.target.value)}>
          {PLANES.map((p) => <option key={p.c} value={p.c}>{p.l} — {fmtCOP(p.tarifa)}</option>)}
        </select>
      </Campo>
      {plan && (
        <div style={S.avisoInfo}>
          Tarifa {plan.c === "suelto" ? "por paseo" : "mensual"}: <b>{fmtCOP(plan.tarifa)}</b> · modalidad {plan.modalidad}
        </div>
      )}
      <button style={S.btnPrimario} onClick={guardar}>{inicial ? "Guardar cambios" : "Registrar dueño"}</button>
      {inicial && <button style={S.btnEliminar} onClick={eliminar}>Dar de baja</button>}
    </Modal>
  );
}

/* ======================================================================= */
/*                     DETALLE DEL PERRO (FASE 2)                          */
/*   Solo lee y presenta datos existentes. No crea entidades nuevas.       */
/* ======================================================================= */
function DetallePerro({ ctx, perroId, onCerrar }) {
  const { perros, duenos, paseos, pagos } = ctx;
  const perro = perros.find((p) => p.id === perroId);
  const [seccion, setSeccion] = useState("ficha"); // ficha | paseos | pagos
  const [editar, setEditar] = useState(false);
  const [reporteAbierto, setReporteAbierto] = useState(false);

  if (!perro) return null;
  const dueno = duenos.find((d) => d.id === perro.dueno_id);

  // Paseos de este perro, del más reciente al más antiguo
  const paseosPerro = paseos
    .filter((w) => w.perro_ids.includes(perro.id))
    .sort((a, b) => (b.fecha + b.id).localeCompare(a.fecha + a.id));

  // Pagos del dueño
  const pagosDueno = dueno
    ? pagos.filter((g) => g.dueno_id === dueno.id).sort((a, b) => b.periodo.localeCompare(a.periodo))
    : [];

  const plan = planPorCodigo(dueno?.plan);

  /* ---------- Indicadores (módulo 5) ---------- */
  const per = periodoActual();
  const paseosMes = paseosPerro.filter((w) => w.fecha.startsWith(per));
  const racha = calcularRacha(paseosPerro.map((w) => w.fecha));
  const pagoMes = pagosDueno.find((g) => g.periodo === per);
  const pagoPendiente = !pagoMes || pagoMes.estado !== "pagado";
  const alertas = [];
  if (perro.vacunas_al_dia === false) alertas.push({ t: "Vacunas pendientes", c: C.rojo });
  if (pagoPendiente && dueno) alertas.push({ t: `Pago de ${nombreMes(per)} pendiente`, c: C.terracota });

  return (
    <div style={S.detalleOverlay}>
      {/* Barra superior */}
      <div style={S.detalleTop}>
        <button style={S.volverBtn} onClick={onCerrar}>‹ Volver</button>
        <button style={S.editarLink} onClick={() => setEditar(true)}>Editar</button>
      </div>

      <div style={S.detalleScroll}>
        {/* Encabezado del perro */}
        <div style={S.detHero}>
          <div style={S.detAvatar}>{perro.emoji || "🐶"}</div>
          <div style={{ flex: 1, minWidth: 0 }}>
            <div style={{ display: "flex", alignItems: "center", gap: 8, flexWrap: "wrap" }}>
              <span style={S.detNombre}>{perro.nombre}</span>
              {esCME(perro.condicion) && <span style={S.chipCME}>Solo individual</span>}
            </div>
            <div style={S.detSub}>{perro.raza || "Sin raza"} · {perro.edad || "edad —"}</div>
            {dueno && <div style={S.detSub}>🏠 {perro.torre_apto || dueno.torre_apto}</div>}
          </div>
        </div>

        {/* Alertas */}
        {alertas.length > 0 && (
          <div style={S.alertasCaja}>
            {alertas.map((a, i) => (
              <div key={i} style={{ ...S.alertaFila, color: a.c }}>
                <span>⚠️</span><span style={{ fontWeight: 700 }}>{a.t}</span>
              </div>
            ))}
          </div>
        )}

        {/* Indicadores rápidos */}
        <div style={S.indicadores}>
          <MiniKpi valor={paseosMes.length} label={`Paseos en ${nombreMes(per)}`} />
          <MiniKpi valor={racha} label={racha === 1 ? "día de racha" : "días de racha"} />
          <MiniKpi valor={paseosPerro.length} label="Paseos totales" />
        </div>

        {/* Acción principal: reporte del día */}
        <button style={S.btnReporte} onClick={() => setReporteAbierto(true)}>
          💬 Generar reporte para el dueño
        </button>

        {/* Sub-navegación del detalle */}
        <div style={S.detTabs}>
          {[["ficha", "Ficha"], ["paseos", "Paseos"], ["pagos", "Pagos"]].map(([c, l]) => (
            <button key={c} onClick={() => setSeccion(c)}
              style={{ ...S.detTab, ...(seccion === c ? S.detTabOn : {}) }}>{l}</button>
          ))}
        </div>

        {/* ---- Módulo 1: Ficha ---- */}
        {seccion === "ficha" && (
          <div style={{ padding: "0 18px 24px" }}>
            <Bloque titulo="Datos del perro">
              <Dato k="Tamaño" v={TAMANOS.find((t) => t.c === perro.tamano)?.l} />
              <Dato k="Energía" v={ENERGIAS.find((e) => e.c === perro.energia)?.l} />
              <Dato k="Temperamento" v={TEMPERAMENTOS.find((t) => t.c === perro.temperamento)?.l} />
              <Dato k="Condición" v={CONDICIONES.find((c) => c.c === perro.condicion)?.l} />
            </Bloque>

            <Bloque titulo="Salud">
              <Dato k="Vacunas al día" v={perro.vacunas_al_dia === false ? "No" : "Sí"}
                alerta={perro.vacunas_al_dia === false} />
              <Dato k="Alergias" v={perro.alergias || "Ninguna"} />
              {perro.notas_salud && <Dato k="Notas" v={perro.notas_salud} />}
            </Bloque>

            {dueno && (
              <Bloque titulo="Dueño y plan">
                <Dato k="Nombre" v={dueno.nombre} />
                <Dato k="Ubicación" v={dueno.torre_apto} />
                <Dato k="Teléfono" v={dueno.telefono || "—"} />
                {plan && <Dato k="Plan" v={`${plan.l} · ${fmtCOP(plan.tarifa)}`} />}
                {dueno.telefono && (
                  <a href={`https://wa.me/${telWa(dueno.telefono)}`} target="_blank" rel="noreferrer"
                    style={S.btnWa}>💬 Escribirle por WhatsApp</a>
                )}
              </Bloque>
            )}
          </div>
        )}

        {/* ---- Módulo 2: Historial de paseos ---- */}
        {seccion === "paseos" && (
          <HistorialPaseos paseos={paseosPerro} />
        )}

        {/* ---- Módulo 3: Historial de pagos ---- */}
        {seccion === "pagos" && (
          <HistorialPagos pagos={pagosDueno} plan={plan} dueno={dueno} />
        )}
      </div>

      {/* Modal de edición (reusa el form de Fase 1) */}
      {editar && <FormPerro ctx={ctx} inicial={perro} onCerrar={() => setEditar(false)} />}

      {/* Modal de reporte compartible (módulo 4) */}
      {reporteAbierto && (
        <ReportePaseo perro={perro} dueno={dueno} paseos={paseosPerro}
          onCerrar={() => setReporteAbierto(false)} />
      )}
    </div>
  );
}

/* Racha: días consecutivos con paseo, contando hacia atrás desde el último */
function calcularRacha(fechasISO) {
  if (!fechasISO.length) return 0;
  const set = new Set(fechasISO);
  const orden = [...set].sort().reverse();
  let racha = 0;
  let cursor = orden[0];
  while (set.has(cursor)) {
    racha++;
    const d = new Date(cursor + "T12:00:00");
    d.setDate(d.getDate() - 1);
    cursor = d.toISOString().slice(0, 10);
  }
  return racha;
}

/* ---- Módulo 2: lista de paseos filtrable por mes ---- */
function HistorialPaseos({ paseos }) {
  const meses = mesesRecientes(6);
  const [mesSel, setMesSel] = useState("todos");
  const lista = mesSel === "todos" ? paseos : paseos.filter((w) => w.fecha.startsWith(mesSel));

  return (
    <div style={{ padding: "0 18px 24px" }}>
      <div style={S.filtroFila}>
        <button style={mesSel === "todos" ? S.filtroOn : S.filtro} onClick={() => setMesSel("todos")}>Todos</button>
        {meses.map((m) => (
          <button key={m} style={mesSel === m ? S.filtroOn : S.filtro} onClick={() => setMesSel(m)}>
            {nombreMes(m)}
          </button>
        ))}
      </div>

      {lista.length === 0 ? (
        <Vacio icono="🚶" titulo="Sin paseos" texto="No hay paseos registrados en este periodo." />
      ) : (
        lista.map((w) => {
          const ronda = RONDAS.find((r) => r.c === w.ronda);
          return (
            <div key={w.id} style={S.paseoItem}>
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                <span style={{ fontWeight: 800, color: C.carbon }}>{fmtFechaCorta(w.fecha)}</span>
                <span style={{ fontSize: 12, color: C.gris }}>{ronda?.l.split(" · ")[0]} · {w.duracion || "—"} min</span>
              </div>
              {w.nota && <div style={S.paseoNota}>“{w.nota}”</div>}
            </div>
          );
        })
      )}
    </div>
  );
}

/* ---- Módulo 3: historial de pagos ---- */
function HistorialPagos({ pagos, plan, dueno }) {
  if (!dueno) {
    return <div style={{ padding: 30 }}><Vacio icono="💵" titulo="Sin dueño" texto="Este perro no tiene dueño asignado." /></div>;
  }
  const meses = mesesRecientes(6);
  const totalPagado = pagos.filter((g) => g.estado === "pagado").reduce((s, g) => s + (g.monto || 0), 0);
  const totalPend = pagos.filter((g) => g.estado !== "pagado").reduce((s, g) => s + (g.monto || 0), 0);

  return (
    <div style={{ padding: "0 18px 24px" }}>
      <div style={S.resumenPagos}>
        <div style={{ flex: 1 }}>
          <div style={{ fontSize: 12, color: C.gris }}>Total pagado</div>
          <div style={{ fontSize: 18, fontWeight: 800, color: C.verde }}>{fmtCOP(totalPagado)}</div>
        </div>
        {totalPend > 0 && (
          <div style={{ flex: 1 }}>
            <div style={{ fontSize: 12, color: C.gris }}>Pendiente</div>
            <div style={{ fontSize: 18, fontWeight: 800, color: C.rojo }}>{fmtCOP(totalPend)}</div>
          </div>
        )}
      </div>

      {meses.map((m) => {
        const g = pagos.find((x) => x.periodo === m);
        const pagado = g?.estado === "pagado";
        const monto = g?.monto ?? plan?.tarifa ?? 0;
        return (
          <div key={m} style={S.pagoMesItem}>
            <div>
              <div style={{ fontWeight: 700, color: C.carbon }}>{nombreMes(m)}</div>
              {pagado && g.fecha_pago && <div style={{ fontSize: 11.5, color: C.gris }}>Pagó el {fmtFechaCorta(g.fecha_pago)}</div>}
            </div>
            <div style={{ textAlign: "right" }}>
              <div style={{ fontWeight: 700, color: pagado ? C.verde : C.gris }}>{fmtCOP(monto)}</div>
              <span style={pagado ? S.badgeMiniPag : S.badgeMiniPend}>{pagado ? "Pagado" : "Pendiente"}</span>
            </div>
          </div>
        );
      })}
    </div>
  );
}

/* ---- Módulo 4: reporte compartible por WhatsApp ---- */
function ReportePaseo({ perro, dueno, paseos, onCerrar }) {
  // Por defecto toma el paseo más reciente
  const [idx, setIdx] = useState(0);
  const [copiado, setCopiado] = useState(false);
  const paseo = paseos[idx];

  const texto = paseo ? construirReporte(perro, paseo) : "";

  const copiar = async () => {
    try {
      await navigator.clipboard.writeText(texto);
      setCopiado(true);
      setTimeout(() => setCopiado(false), 2000);
    } catch (e) {
      // Fallback: seleccionar el textarea
      const ta = document.getElementById("reporte-ta");
      if (ta) { ta.select(); document.execCommand("copy"); setCopiado(true); setTimeout(() => setCopiado(false), 2000); }
    }
  };

  const waUrl = dueno?.telefono
    ? `https://wa.me/${telWa(dueno.telefono)}?text=${encodeURIComponent(texto)}`
    : `https://wa.me/?text=${encodeURIComponent(texto)}`;

  return (
    <Modal titulo="Reporte para el dueño" onCerrar={onCerrar}>
      {!paseo ? (
        <Vacio icono="🚶" titulo="Sin paseos" texto="Registrá un paseo de este perro para poder generar el reporte." />
      ) : (
        <>
          <Campo label="¿De cuál paseo?">
            <select style={S.input} value={idx} onChange={(e) => setIdx(Number(e.target.value))}>
              {paseos.slice(0, 10).map((w, i) => (
                <option key={w.id} value={i}>
                  {fmtFechaCorta(w.fecha)} · {RONDAS.find((r) => r.c === w.ronda)?.l.split(" · ")[0]}
                </option>
              ))}
            </select>
          </Campo>

          <div style={S.reporteBox}>
            <textarea id="reporte-ta" readOnly value={texto} style={S.reporteTa} />
          </div>

          <button style={S.btnPrimario} onClick={copiar}>
            {copiado ? "✓ ¡Copiado!" : "📋 Copiar texto"}
          </button>
          <a href={waUrl} target="_blank" rel="noreferrer" style={S.btnWaFull}>
            💬 Enviar por WhatsApp{dueno?.telefono ? ` a ${dueno.nombre.split(" ")[0]}` : ""}
          </a>
          {!dueno?.telefono && (
            <div style={{ ...S.avisoInfo, marginTop: 12 }}>
              Este dueño no tiene teléfono guardado. El botón abre WhatsApp con el texto listo para que elijás a quién enviarlo.
            </div>
          )}
        </>
      )}
    </Modal>
  );
}

/* Texto cálido, registro paisa, para el reporte del día */
function construirReporte(perro, paseo) {
  const ronda = RONDAS.find((r) => r.c === paseo.ronda);
  const franja = ronda ? ronda.l.split(" · ")[1] : "";
  const saludo = `¡Hola! 🐾 Le cuento cómo le fue a ${perro.nombre} hoy.`;
  const cuando = `📅 ${fmtFechaLarga(paseo.fecha)}${franja ? ` (${franja})` : ""}`;
  const duracion = paseo.duracion ? `\n⏱️ Paseamos ${paseo.duracion} minutos.` : "";
  const comportamiento = paseo.nota
    ? `\n\n${perro.nombre} ${paseo.nota.charAt(0).toLowerCase() + paseo.nota.slice(1)}`
    : `\n\n${perro.nombre} disfrutó su paseo y volvió feliz. 🐶`;
  const cierre = `\n\n¡Cualquier cosa me avisás! 💚\nCaninatas`;
  return `${saludo}\n${cuando}${duracion}${comportamiento}${cierre}`;
}

/* Sub-componentes de presentación del detalle */
function Bloque({ titulo, children }) {
  return (
    <div style={S.detBloque}>
      <div style={S.detBloqueTit}>{titulo}</div>
      {children}
    </div>
  );
}
function Dato({ k, v, alerta }) {
  return (
    <div style={S.datoFila}>
      <span style={S.datoK}>{k}</span>
      <span style={{ ...S.datoV, color: alerta ? C.rojo : C.carbon, fontWeight: alerta ? 700 : 600 }}>{v || "—"}</span>
    </div>
  );
}
function MiniKpi({ valor, label }) {
  return (
    <div style={S.miniKpi}>
      <div style={{ fontSize: 24, fontWeight: 800, color: C.verde }}>{valor}</div>
      <div style={{ fontSize: 11, color: C.gris, lineHeight: 1.2 }}>{label}</div>
    </div>
  );
}

/* ======================================================================= */
/*                          AGENDA (FASE 3)                                */
/*   Motor de agendamiento: calendario, cupos, estados, reglas duras.      */
/* ======================================================================= */

/* ---- Motor de reglas: valida si un paseo se puede guardar ---- */
// Cuenta servicios (perros) de un día, opcionalmente excluyendo un paseo.
// No cuenta cancelados ni reprogramados.
function serviciosDelDia(paseos, fecha, excluirId = null) {
  return paseos
    .filter((w) => w.fecha === fecha && w.id !== excluirId && !["cancelado", "reprogramado"].includes(w.estado))
    .reduce((s, w) => s + w.perro_ids.length, 0);
}
function serviciosDeRonda(paseos, fecha, ronda, excluirId = null) {
  return paseos
    .filter((w) => w.fecha === fecha && w.ronda === ronda && w.id !== excluirId && !["cancelado", "reprogramado"].includes(w.estado))
    .reduce((s, w) => s + w.perro_ids.length, 0);
}
// Devuelve { ok, errores[] } para un intento de guardar
function validarPaseo(paseo, perros, todosPaseos) {
  const errores = [];
  const seleccion = paseo.perro_ids.map((id) => perros.find((p) => p.id === id)).filter(Boolean);
  const hayCME = seleccion.some((p) => esCME(p.condicion));

  if (paseo.perro_ids.length === 0) errores.push("Elegí al menos un perro.");
  // Regla CME (§4.4)
  if (hayCME && paseo.perro_ids.length > 1)
    errores.push("Un Canino de Manejo Especial solo puede ir en paseo individual.");
  if (hayCME && paseo.modalidad !== "individual")
    errores.push("Este paseo debe ser individual por incluir un CME.");
  // Tope de grupo (§4.3)
  if (paseo.perro_ids.length > CUPO_RONDA)
    errores.push(`Máximo ${CUPO_RONDA} perros por grupo.`);
  // Cupo de la ronda: los ya agendados + estos no superan 4
  const yaEnRonda = serviciosDeRonda(todosPaseos, paseo.fecha, paseo.ronda, paseo.id);
  if (yaEnRonda + paseo.perro_ids.length > CUPO_RONDA)
    errores.push(`Esa ronda ya tiene ${yaEnRonda} de ${CUPO_RONDA} cupos. No caben ${paseo.perro_ids.length} más.`);
  // Tope diario (§4.5)
  const yaEnDia = serviciosDelDia(todosPaseos, paseo.fecha, paseo.id);
  if (yaEnDia + paseo.perro_ids.length > CAPACIDAD_DIA)
    errores.push(`El día llegaría a ${yaEnDia + paseo.perro_ids.length} servicios (tope: ${CAPACIDAD_DIA}).`);

  return { ok: errores.length === 0, errores };
}

function Agenda({ ctx }) {
  const { paseos } = ctx;
  const [vista, setVista] = useState("hoy"); // hoy | semana
  const [lunes, setLunes] = useState(lunesDeSemana(hoyISO()));
  const [programar, setProgramar] = useState(null); // {fecha, ronda} | null
  const [editarPaseo, setEditarPaseo] = useState(null);

  const abrirProgramar = (pref) => { setEditarPaseo(null); setProgramar(pref || {}); };
  const abrirEditar = (w) => { setProgramar(null); setEditarPaseo(w); };

  return (
    <div>
      <Header titulo="Agenda" sub="Programá y controlá los paseos" />

      <div style={S.segmento}>
        <button style={vista === "hoy" ? S.segActivo : S.segItem} onClick={() => setVista("hoy")}>Hoy</button>
        <button style={vista === "semana" ? S.segActivo : S.segItem} onClick={() => setVista("semana")}>Semana</button>
      </div>

      {vista === "hoy" && <VistaHoy ctx={ctx} onEditar={abrirEditar} onProgramar={abrirProgramar} />}
      {vista === "semana" && (
        <VistaSemana ctx={ctx} lunes={lunes} setLunes={setLunes}
          onProgramar={abrirProgramar} onEditar={abrirEditar} />
      )}

      <button style={S.fabAncho} onClick={() => abrirProgramar()}>+ Programar paseo</button>

      {(programar || editarPaseo) && (
        <FormProgramar ctx={ctx} pref={programar} inicial={editarPaseo}
          onCerrar={() => { setProgramar(null); setEditarPaseo(null); }} />
      )}
    </div>
  );
}

/* ---- Módulo 5: Vista "Hoy" ---- */
function VistaHoy({ ctx, onEditar, onProgramar }) {
  const { paseos, perros } = ctx;
  const hoy = hoyISO();
  const delDia = paseos
    .filter((w) => w.fecha === hoy && !["cancelado", "reprogramado"].includes(w.estado))
    .sort((a, b) => RONDAS.findIndex((r) => r.c === a.ronda) - RONDAS.findIndex((r) => r.c === b.ronda));
  const servicios = serviciosDelDia(paseos, hoy);

  return (
    <div>
      <div style={S.hoyResumen}>
        <div>
          <div style={{ fontSize: 13, color: C.gris }}>{DIAS_LARGO[diaSemana(hoy)]}, {Number(hoy.split("-")[2])}</div>
          <div style={{ fontSize: 15, fontWeight: 700, color: C.carbon }}>
            {delDia.length} paseo{delDia.length !== 1 ? "s" : ""} · {servicios} servicio{servicios !== 1 ? "s" : ""}
          </div>
        </div>
        <BarraCupoDia servicios={servicios} />
      </div>

      {delDia.length === 0 && (
        <Vacio icono="🗓️" titulo="Nada programado para hoy"
          texto="Programá un paseo o esperá a mañana. La app respeta la pausa de calor de 11 a 3." />
      )}

      {delDia.map((w) => (
        <TarjetaAgenda key={w.id} paseo={w} perros={perros}
          onEditar={() => onEditar(w)} ctx={ctx} accionesRapidas />
      ))}
    </div>
  );
}

/* ---- Módulo 1: Calendario semanal ---- */
function VistaSemana({ ctx, lunes, setLunes, onProgramar, onEditar }) {
  const { paseos, perros } = ctx;
  const dias = semanaDesde(lunes);
  const hoy = hoyISO();
  const [diaSel, setDiaSel] = useState(dias.includes(hoy) ? hoy : lunes);

  // Si cambia la semana y el día seleccionado no está, cae al lunes
  useEffect(() => {
    if (!dias.includes(diaSel)) setDiaSel(dias.includes(hoy) ? hoy : lunes);
  }, [lunes]); // eslint-disable-line

  const rangoTxt = `${Number(dias[0].split("-")[2])} ${MESES_LARGO[Number(dias[0].split("-")[1]) - 1].slice(0, 3)} – ${Number(dias[6].split("-")[2])} ${MESES_LARGO[Number(dias[6].split("-")[1]) - 1].slice(0, 3)}`;

  return (
    <div>
      {/* Navegación de semana */}
      <div style={S.semNav}>
        <button style={S.semFlecha} onClick={() => setLunes(sumarDias(lunes, -7))}>‹</button>
        <div style={{ textAlign: "center" }}>
          <div style={{ fontWeight: 800, color: C.carbon, fontSize: 15 }}>{rangoTxt}</div>
          <button style={S.hoyLink} onClick={() => { setLunes(lunesDeSemana(hoy)); setDiaSel(hoy); }}>Ir a hoy</button>
        </div>
        <button style={S.semFlecha} onClick={() => setLunes(sumarDias(lunes, 7))}>›</button>
      </div>

      {/* Tira de días */}
      <div style={S.tiraDias}>
        {dias.map((d) => {
          const serv = serviciosDelDia(paseos, d);
          const lleno = serv >= CAPACIDAD_DIA;
          const esHoy = d === hoy;
          const sel = d === diaSel;
          return (
            <button key={d} onClick={() => setDiaSel(d)}
              style={{ ...S.diaChip, ...(sel ? S.diaChipOn : {}), ...(esHoy && !sel ? S.diaChipHoy : {}) }}>
              <span style={{ fontSize: 10, opacity: 0.8 }}>{DIAS_CORTO[diaSemana(d)]}</span>
              <span style={{ fontSize: 17, fontWeight: 800 }}>{Number(d.split("-")[2])}</span>
              <span style={{ ...S.puntoCupo, background: serv === 0 ? "transparent" : lleno ? C.rojo : C.verdeClaro }} />
            </button>
          );
        })}
      </div>

      {/* Rondas del día seleccionado */}
      <DiaPorRondas ctx={ctx} fecha={diaSel} onProgramar={onProgramar} onEditar={onEditar} />
    </div>
  );
}

/* Detalle de un día partido en rondas, con la franja de calor bloqueada */
function DiaPorRondas({ ctx, fecha, onProgramar, onEditar }) {
  const { paseos, perros } = ctx;

  return (
    <div style={{ padding: "4px 18px 10px" }}>
      {RONDAS.map((r, i) => {
        const enRonda = paseos.filter((w) => w.fecha === fecha && w.ronda === r.c && !["cancelado", "reprogramado"].includes(w.estado));
        const serv = enRonda.reduce((s, w) => s + w.perro_ids.length, 0);
        const lleno = serv >= CUPO_RONDA;

        return (
          <React.Fragment key={r.c}>
            {/* Bloque de pausa de calor entre ronda 2 y 3 */}
            {i === 2 && (
              <div style={S.franjaCalor}>
                <span style={{ fontSize: 18 }}>☀️</span>
                <div>
                  <div style={{ fontWeight: 800, fontSize: 13.5, color: "#9A6A00" }}>Pausa de calor · 11:00 a.m. – 3:00 p.m.</div>
                  <div style={{ fontSize: 12, color: "#9A6A00", opacity: 0.85 }}>No se agenda: riesgo de golpe de calor en las lomas.</div>
                </div>
              </div>
            )}

            <div style={S.rondaBloque}>
              <div style={S.rondaHead}>
                <div>
                  <div style={{ fontWeight: 800, color: C.carbon, fontSize: 14.5 }}>{r.l.split(" · ")[0]}</div>
                  <div style={{ fontSize: 12, color: C.gris }}>{r.l.split(" · ")[1]}</div>
                </div>
                <span style={{ ...S.cupoBadge, ...(lleno ? S.cupoBadgeLleno : {}) }}>{serv}/{CUPO_RONDA}</span>
              </div>

              {enRonda.map((w) => (
                <TarjetaAgenda key={w.id} paseo={w} perros={perros} onEditar={() => onEditar(w)} ctx={ctx} compacta />
              ))}

              {!lleno ? (
                <button style={S.agregarRonda} onClick={() => onProgramar({ fecha, ronda: r.c })}>
                  + Agregar a esta ronda
                </button>
              ) : (
                <div style={S.rondaLlena}>Ronda llena</div>
              )}
            </div>
          </React.Fragment>
        );
      })}
    </div>
  );
}

/* Tarjeta de un paseo en la agenda, con estados y acciones rápidas */
function TarjetaAgenda({ paseo, perros, onEditar, ctx, accionesRapidas, compacta }) {
  const { guardarPaseo } = ctx;
  const est = estadoPorC(paseo.estado);
  const asistentes = paseo.perro_ids.map((id) => perros.find((p) => p.id === id)).filter(Boolean);
  const ronda = rondaPorC(paseo.ronda);

  const cambiarEstado = async (nuevo) => {
    await guardarPaseo({ ...paseo, estado: nuevo });
  };

  return (
    <div style={{ ...S.agCard, ...(compacta ? { margin: "8px 0 0" } : {}) }}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", gap: 8 }}>
        <button onClick={onEditar} style={S.agCardBody}>
          <div style={{ display: "flex", gap: 6, flexWrap: "wrap", alignItems: "center", marginBottom: 4 }}>
            {!compacta && <span style={{ fontSize: 12, fontWeight: 700, color: C.gris }}>{ronda?.l.split(" · ")[0]}</span>}
            <span style={paseo.modalidad === "individual" ? S.chipIndiv : S.chipGrupal}>
              {paseo.modalidad === "individual" ? "Individual" : "Grupal"}
            </span>
          </div>
          <div style={{ display: "flex", gap: 5, flexWrap: "wrap" }}>
            {asistentes.map((p) => (
              <span key={p.id} style={S.perroMini}>{p.emoji || "🐶"} {p.nombre}</span>
            ))}
          </div>
        </button>
        <span style={{ ...S.estadoBadge, color: est.color, background: est.bg }}>{est.l}</span>
      </div>

      {/* Acciones rápidas según estado */}
      {accionesRapidas && paseo.estado === "programado" && (
        <div style={S.agAcciones}>
          <button style={S.accInicio} onClick={() => cambiarEstado("en_curso")}>▶ Iniciar</button>
          <button style={S.accCancelar} onClick={() => cambiarEstado("cancelado")}>Cancelar</button>
        </div>
      )}
      {accionesRapidas && paseo.estado === "en_curso" && (
        <div style={S.agAcciones}>
          <button style={S.accFin} onClick={() => cambiarEstado("completado")}>✓ Terminar paseo</button>
        </div>
      )}
      {accionesRapidas && paseo.estado === "completado" && (
        <div style={S.agHint}>Guardado en la bitácora ✓</div>
      )}
    </div>
  );
}

function BarraCupoDia({ servicios }) {
  const pct = Math.min(100, Math.round((servicios / CAPACIDAD_DIA) * 100));
  const color = pct >= 100 ? C.rojo : pct > 80 ? C.terracota : C.verdeClaro;
  return (
    <div style={{ textAlign: "right", minWidth: 90 }}>
      <div style={{ fontSize: 12, color: C.gris, marginBottom: 3 }}>{servicios}/{CAPACIDAD_DIA} del día</div>
      <div style={{ width: 90, height: 7, borderRadius: 20, background: C.arena, overflow: "hidden" }}>
        <div style={{ width: `${pct}%`, height: "100%", background: color, borderRadius: 20 }} />
      </div>
    </div>
  );
}

/* ---- Módulos 2, 3 y 4: Programar / editar con validación dura ---- */
function FormProgramar({ ctx, pref, inicial, onCerrar }) {
  const { perros, paseos, guardarPaseo } = ctx;
  const activos = perros.filter((p) => p.activo !== false);

  const [f, setF] = useState(inicial || {
    fecha: pref?.fecha || hoyISO(),
    ronda: pref?.ronda || "ronda1",
    modalidad: "grupal",
    perro_ids: [],
    duracion: 55,
    nota: "",
    estado: "programado",
  });
  const set = (k, v) => setF((s) => ({ ...s, [k]: v }));

  // Validación en tiempo real
  const { ok, errores } = validarPaseo(f, activos, paseos);
  const hayCME = f.perro_ids.some((id) => esCME(activos.find((x) => x.id === id)?.condicion));

  // Cupo disponible en la ronda elegida (excluyendo este paseo si se edita)
  const usadoRonda = serviciosDeRonda(paseos, f.fecha, f.ronda, f.id);
  const usadoDia = serviciosDelDia(paseos, f.fecha, f.id);

  const togglePerro = (p) => {
    const ya = f.perro_ids.includes(p.id);
    if (ya) {
      const nuevos = f.perro_ids.filter((id) => id !== p.id);
      setF((s) => ({ ...s, perro_ids: nuevos, modalidad: nuevos.length <= 1 ? s.modalidad : "grupal" }));
      return;
    }
    // Agregar: aplicar reglas CME en el acto
    if (esCME(p.condicion)) {
      setF((s) => ({ ...s, perro_ids: [p.id], modalidad: "individual" }));
      return;
    }
    if (hayCME) return; // ya hay un CME; bloqueado
    if (f.perro_ids.length >= CUPO_RONDA) return;
    if (usadoRonda + f.perro_ids.length + 1 > CUPO_RONDA) return; // no cabe en la ronda
    const nuevos = [...f.perro_ids, p.id];
    setF((s) => ({ ...s, perro_ids: nuevos, modalidad: nuevos.length > 1 ? "grupal" : s.modalidad }));
  };

  const guardar = async () => {
    if (!ok) return;
    await guardarPaseo(f);
    onCerrar();
  };

  const reprogramar = async () => {
    // Marca el actual como reprogramado y crea uno nuevo copiando datos
    await guardarPaseo({ ...inicial, estado: "reprogramado" });
    await guardarPaseo({
      fecha: f.fecha, ronda: f.ronda, modalidad: f.modalidad,
      perro_ids: f.perro_ids, duracion: f.duracion, nota: f.nota, estado: "programado",
    });
    onCerrar();
  };

  const rondaActual = rondaPorC(f.ronda);

  return (
    <Modal titulo={inicial ? "Editar paseo programado" : "Programar paseo"} onCerrar={onCerrar}>
      <Campo label="Fecha">
        <input style={S.input} type="date" value={f.fecha} min={hoyISO()}
          onChange={(e) => set("fecha", e.target.value)} />
      </Campo>

      <Campo label="Ronda">
        <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
          {RONDAS.map((r) => {
            const usado = serviceCupo(paseos, f.fecha, r.c, f.id);
            const lleno = usado >= CUPO_RONDA;
            const sel = f.ronda === r.c;
            return (
              <button key={r.c} onClick={() => !lleno && set("ronda", r.c)} disabled={lleno && !sel}
                style={{ ...S.rondaOpcion, ...(sel ? S.rondaOpcionOn : {}), opacity: lleno && !sel ? 0.45 : 1 }}>
                <div style={{ textAlign: "left" }}>
                  <div style={{ fontWeight: 700, fontSize: 14 }}>{r.l.split(" · ")[0]}</div>
                  <div style={{ fontSize: 11.5, color: sel ? "#EAF3EE" : C.gris }}>{r.l.split(" · ")[1]}</div>
                </div>
                <span style={{ fontSize: 12, fontWeight: 700 }}>{lleno ? "Llena" : `${usado}/${CUPO_RONDA}`}</span>
              </button>
            );
          })}
        </div>
      </Campo>

      <div style={S.avisoInfo}>
        📅 {DIAS_LARGO[diaSemana(f.fecha)]} · {rondaActual?.l.split(" · ")[1]} · el día va en {usadoDia}/{CAPACIDAD_DIA} servicios.
      </div>

      <Campo label={`Perros (${f.perro_ids.length}${hayCME ? "" : `/${CUPO_RONDA}`})`}>
        <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
          {activos.map((p) => {
            const marcado = f.perro_ids.includes(p.id);
            const cme = esCME(p.condicion);
            const sinCupoRonda = !marcado && (usadoRonda + f.perro_ids.length >= CUPO_RONDA) && !cme;
            const bloqueado = !marcado && ((f.perro_ids.length >= CUPO_RONDA && !cme) || hayCME || sinCupoRonda);
            return (
              <button key={p.id} disabled={bloqueado} onClick={() => togglePerro(p)}
                style={{ ...S.filaAsistencia, ...(marcado ? S.filaAsistenciaOn : {}), opacity: bloqueado ? 0.4 : 1 }}>
                <span style={{ fontSize: 22 }}>{p.emoji || "🐶"}</span>
                <div style={{ flex: 1, textAlign: "left" }}>
                  <div style={{ fontWeight: 600, color: C.carbon }}>
                    {p.nombre} {cme && <span style={S.chipCMEmini}>CME</span>}
                  </div>
                  <div style={{ fontSize: 12, color: C.gris }}>{p.torre_apto}</div>
                </div>
                <span style={{ ...S.checkbox, ...(marcado ? S.checkboxOn : {}) }}>{marcado ? "✓" : ""}</span>
              </button>
            );
          })}
        </div>
      </Campo>

      {hayCME && <div style={S.avisoInfo}>🛡️ Paseo individual obligatorio: incluye un Canino de Manejo Especial.</div>}

      <Campo label="Duración estimada (min)">
        <input style={S.input} inputMode="numeric" value={f.duracion}
          onChange={(e) => set("duracion", e.target.value.replace(/[^\d]/g, ""))} placeholder="55" />
      </Campo>

      {/* Errores de validación */}
      {!ok && f.perro_ids.length > 0 && (
        <div style={S.avisoPeligro}>
          {errores.map((e, i) => <div key={i}>• {e}</div>)}
        </div>
      )}

      <button style={{ ...S.btnPrimario, opacity: ok ? 1 : 0.5 }} disabled={!ok} onClick={guardar}>
        {inicial ? "Guardar cambios" : "Programar paseo"}
      </button>

      {inicial && (
        <button style={S.btnReprogramar} disabled={!ok} onClick={reprogramar}>
          🔁 Reprogramar (mover a esta fecha/ronda)
        </button>
      )}
    </Modal>
  );
}
// alias corto usado arriba
function serviceCupo(paseos, fecha, ronda, excluirId) {
  return serviciosDeRonda(paseos, fecha, ronda, excluirId);
}

/* ======================================================================= */
/*                                PASEOS                                   */
/* ======================================================================= */
function Paseos({ ctx }) {
  const { paseos, perros } = ctx;
  const [modal, setModal] = useState(false);
  const [editar, setEditar] = useState(null);

  const ordenados = [...paseos].sort((a, b) => (b.fecha + b.id).localeCompare(a.fecha + a.id));

  return (
    <div>
      <Header titulo="Bitácora de Paseos" sub={`${paseos.length} paseos registrados`} />

      {ordenados.length === 0 && (
        <Vacio icono="🚶" titulo="Sin paseos aún"
          texto="Registrá el primer paseo del día para llevar la asistencia de la manada." />
      )}

      {ordenados.map((w) => (
        <TarjetaPaseo key={w.id} paseo={w} perros={perros}
          onEdit={() => { setEditar(w); setModal(true); }} />
      ))}

      <button style={S.fabAncho} onClick={() => { setEditar(null); setModal(true); }}>
        + Registrar paseo
      </button>

      {modal && <FormPaseo ctx={ctx} inicial={editar} onCerrar={() => setModal(false)} />}
    </div>
  );
}

function TarjetaPaseo({ paseo, perros, onEdit }) {
  const ronda = RONDAS.find((r) => r.c === paseo.ronda);
  const asistentes = paseo.perro_ids.map((id) => perros.find((p) => p.id === id)).filter(Boolean);
  return (
    <button style={S.card} onClick={onEdit}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
        <div style={{ textAlign: "left" }}>
          <div style={S.cardTitulo}>{paseo.fecha}</div>
          <div style={S.cardSub}>{ronda?.l || paseo.ronda} · {paseo.duracion || "—"} min</div>
        </div>
        <span style={paseo.modalidad === "individual" ? S.chipIndiv : S.chipGrupal}>
          {paseo.modalidad === "individual" ? "Individual" : "Grupal"}
        </span>
      </div>
      <div style={S.tagsFila}>
        {asistentes.map((p) => <Tag key={p.id} color={C.cielo} dark>{p.emoji || "🐶"} {p.nombre}</Tag>)}
      </div>
      {paseo.nota && <div style={S.notaPaseo}>“{paseo.nota}”</div>}
    </button>
  );
}

/* ------------------------ Formulario Paseo ----------------------------- */
function FormPaseo({ ctx, inicial, onCerrar }) {
  const { perros, guardarPaseo } = ctx;
  const activos = perros.filter((p) => p.activo !== false);

  const [f, setF] = useState(inicial || {
    fecha: hoyISO(), ronda: "ronda1", modalidad: "grupal",
    perro_ids: [], duracion: 55, nota: "", estado: "completado",
  });
  const [err, setErr] = useState({});
  const set = (k, v) => setF((s) => ({ ...s, [k]: v }));

  // Advertencia de golpe de calor (§4.2b): franja 11:00–15:00
  const [horaInicio, setHoraInicio] = useState(inicial?.hora_inicio || "");
  const horaRiesgo = (() => {
    if (!horaInicio) return false;
    const h = Number(horaInicio.split(":")[0]);
    const m = Number(horaInicio.split(":")[1] || 0);
    const mins = h * 60 + m;
    return mins >= 11 * 60 && mins < 15 * 60;
  })();

  const togglePerro = (p) => {
    const ya = f.perro_ids.includes(p.id);
    let nuevos;
    if (ya) {
      nuevos = f.perro_ids.filter((id) => id !== p.id);
    } else {
      // Regla CME: si el perro es de manejo especial, el paseo es individual y único (§4.4)
      if (esCME(p.condicion)) {
        setF((s) => ({ ...s, perro_ids: [p.id], modalidad: "individual" }));
        return;
      }
      // Si ya hay un CME seleccionado, no permitir agregar más
      const hayCME = f.perro_ids.some((id) => esCME(activos.find((x) => x.id === id)?.condicion));
      if (hayCME) return;
      if (f.perro_ids.length >= 4) return; // techo de 4 (§4.3)
      nuevos = [...f.perro_ids, p.id];
    }
    const modalidad = nuevos.length === 1 && esCME(activos.find((x) => x.id === nuevos[0])?.condicion)
      ? "individual"
      : (nuevos.length === 1 ? f.modalidad : "grupal");
    setF((s) => ({ ...s, perro_ids: nuevos, modalidad }));
  };

  const validar = () => {
    const e = {};
    if (f.perro_ids.length === 0) e.perros = "Marcá al menos un perro que asistió.";
    setErr(e);
    return Object.keys(e).length === 0;
  };

  const guardar = async () => {
    if (!validar()) return;
    await guardarPaseo({ ...f, hora_inicio: horaInicio });
    onCerrar();
  };

  const hayCMESeleccionado = f.perro_ids.some((id) => esCME(activos.find((x) => x.id === id)?.condicion));

  return (
    <Modal titulo={inicial ? "Editar paseo" : "Nuevo paseo"} onCerrar={onCerrar}>
      <Fila>
        <Campo label="Fecha">
          <input style={S.input} type="date" value={f.fecha} onChange={(e) => set("fecha", e.target.value)} />
        </Campo>
        <Campo label="Hora inicio">
          <input style={S.input} type="time" value={horaInicio} onChange={(e) => setHoraInicio(e.target.value)} />
        </Campo>
      </Fila>

      {horaRiesgo && (
        <div style={S.avisoPeligro}>
          ☀️ <b>Riesgo de golpe de calor.</b> Entre las 11:00 a.m. y las 3:00 p.m. no se pasea:
          las lomas más el calor son peligrosas, sobre todo para razas braquicéfalas y perros mayores.
          Reprogramá para la mañana temprano o la tarde.
        </div>
      )}

      <Campo label="Ronda">
        <select style={S.input} value={f.ronda} onChange={(e) => set("ronda", e.target.value)}>
          {RONDAS.map((r) => <option key={r.c} value={r.c}>{r.l}</option>)}
        </select>
      </Campo>

      <Campo label="Duración (minutos)">
        <input style={S.input} inputMode="numeric" value={f.duracion}
          onChange={(e) => set("duracion", e.target.value.replace(/[^\d]/g, ""))} placeholder="55" />
      </Campo>

      <Campo label={`Asistencia (${f.perro_ids.length}${hayCMESeleccionado ? "" : "/4"})`} error={err.perros}>
        <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
          {activos.map((p) => {
            const marcado = f.perro_ids.includes(p.id);
            const cme = esCME(p.condicion);
            const bloqueado = !marcado && ((f.perro_ids.length >= 4 && !cme) || (hayCMESeleccionado));
            return (
              <button key={p.id} disabled={bloqueado}
                onClick={() => togglePerro(p)}
                style={{
                  ...S.filaAsistencia,
                  ...(marcado ? S.filaAsistenciaOn : {}),
                  opacity: bloqueado ? 0.4 : 1,
                }}>
                <span style={{ fontSize: 22 }}>{p.emoji || "🐶"}</span>
                <div style={{ flex: 1, textAlign: "left" }}>
                  <div style={{ fontWeight: 600, color: C.carbon }}>
                    {p.nombre} {cme && <span style={S.chipCMEmini}>CME</span>}
                  </div>
                  <div style={{ fontSize: 12, color: C.gris }}>{p.torre_apto}</div>
                </div>
                <span style={{ ...S.checkbox, ...(marcado ? S.checkboxOn : {}) }}>{marcado ? "✓" : ""}</span>
              </button>
            );
          })}
        </div>
      </Campo>

      {hayCMESeleccionado && (
        <div style={S.avisoInfo}>🛡️ Paseo individual obligatorio: hay un Canino de Manejo Especial.</div>
      )}

      <Campo label="Nota de comportamiento">
        <textarea style={{ ...S.input, minHeight: 70, resize: "vertical" }} value={f.nota}
          onChange={(e) => set("nota", e.target.value)} placeholder="¿Cómo se portó la manada?" />
      </Campo>

      <button style={S.btnPrimario} onClick={guardar}>{inicial ? "Guardar cambios" : "Registrar paseo"}</button>
    </Modal>
  );
}

/* ======================================================================= */
/*                          PAGOS (FASE 4)                                 */
/*   Estado de cuenta, registro de pagos, recordatorios, pasarela lista.   */
/* ======================================================================= */

// Determina el estado real del pago de un dueño en un periodo dado
function estadoDelMes(pagos, duenoId, periodo, tarifa) {
  const g = pagos.find((x) => x.dueno_id === duenoId && x.periodo === periodo && x.estado !== "anulado");
  if (!g) {
    // Sin registro: pendiente. Vencido si el periodo ya pasó.
    const vencido = periodo < periodoActual();
    return { estado: vencido ? "vencido" : "pendiente", pagado: 0, tarifa, registro: null };
  }
  return { estado: g.estado, pagado: g.monto || 0, tarifa, registro: g };
}

function Pagos({ ctx }) {
  const { duenos, pagos } = ctx;
  const per = periodoActual();
  const activos = duenos.filter((d) => d.activo !== false);

  const [detalleDueno, setDetalleDueno] = useState(null);
  const [registrar, setRegistrar] = useState(null); // {dueno, periodo} | null
  const [recordatorio, setRecordatorio] = useState(null); // dueno | null

  // Cálculo del mes en curso
  const filas = activos.map((d) => {
    const tarifa = planPorCodigo(d.plan)?.tarifa || 0;
    const em = estadoDelMes(pagos, d.id, per, tarifa);
    return { dueno: d, tarifa, ...em };
  });
  const pendientes = filas.filter((f) => !["pagado"].includes(f.estado));
  const totalProyectado = filas.reduce((s, f) => s + f.tarifa, 0);
  const totalCobrado = filas.reduce((s, f) => s + (f.estado === "pagado" ? f.tarifa : f.estado === "parcial" ? f.pagado : 0), 0);
  const totalPend = totalProyectado - totalCobrado;

  return (
    <div>
      <Header titulo="Pagos" sub={nombreMes(per)} />

      {/* Módulo 4: resumen financiero del mes */}
      <div style={S.finResumen}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "baseline" }}>
          <span style={{ fontSize: 13, color: C.gris, fontWeight: 700 }}>Cobrado este mes</span>
          <span style={{ fontSize: 12, color: C.gris }}>de {fmtCOP(totalProyectado)}</span>
        </div>
        <div style={{ fontSize: 30, fontWeight: 800, color: C.verde, margin: "2px 0 8px" }}>{fmtCOP(totalCobrado)}</div>
        <div style={S.finBarra}>
          <div style={{ width: `${totalProyectado ? Math.round(totalCobrado / totalProyectado * 100) : 0}%`, height: "100%", background: C.verde, borderRadius: 20 }} />
        </div>
        <div style={{ display: "flex", justifyContent: "space-between", marginTop: 8, fontSize: 12.5 }}>
          <span style={{ color: C.gris }}>{filas.filter((f) => f.estado === "pagado").length} al día</span>
          <span style={{ color: totalPend > 0 ? C.rojo : C.gris, fontWeight: 700 }}>Falta cobrar {fmtCOP(totalPend)}</span>
        </div>
      </div>

      {/* Recordatorios de cobro (módulo 3) */}
      {pendientes.length > 0 && (
        <div style={S.recordatorioCaja}>
          <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 10 }}>
            <span style={{ fontSize: 22 }}>🔔</span>
            <div style={{ fontWeight: 800, color: C.carbon, fontSize: 14.5 }}>
              {pendientes.length} por cobrar en {nombreMes(per)}
            </div>
          </div>
          {pendientes.map((f) => (
            <button key={f.dueno.id} style={S.recordFila} onClick={() => setRecordatorio(f.dueno)}>
              <div style={{ textAlign: "left" }}>
                <div style={{ fontWeight: 700, color: C.carbon, fontSize: 14 }}>{f.dueno.nombre}</div>
                <div style={{ fontSize: 12, color: C.gris }}>{fmtCOP(f.tarifa)}
                  {f.estado === "vencido" && <span style={{ color: C.rojo, fontWeight: 700 }}> · vencido</span>}
                  {f.estado === "parcial" && <span style={{ color: "#B07A16", fontWeight: 700 }}> · abonó {fmtCOP(f.pagado)}</span>}
                </div>
              </div>
              <span style={S.recordCta}>💬 Recordar</span>
            </button>
          ))}
        </div>
      )}

      {activos.length === 0 && (
        <Vacio icono="💵" titulo="Sin dueños registrados"
          texto="Registrá dueños en la pestaña Manada para controlar sus pagos acá." />
      )}

      {/* Lista de estado de cuenta por dueño (módulo 1) */}
      {filas.map((f) => {
        const est = estadoPagoPorC(f.estado);
        return (
          <div key={f.dueno.id} style={{ ...S.card, cursor: "default" }}>
            <button style={S.cuentaCabecera} onClick={() => setDetalleDueno(f.dueno)}>
              <div style={{ textAlign: "left", flex: 1, minWidth: 0 }}>
                <div style={S.cardTitulo}>{f.dueno.nombre}</div>
                <div style={S.cardSub}>{f.dueno.torre_apto}</div>
                <div style={{ marginTop: 4, fontWeight: 700, color: C.verde }}>{fmtCOP(f.tarifa)}
                  <span style={{ fontSize: 12, color: C.gris, fontWeight: 500 }}> / mes</span>
                </div>
              </div>
              <div style={{ display: "flex", flexDirection: "column", alignItems: "flex-end", gap: 6 }}>
                <span style={{ ...S.estadoBadge, color: est.color, background: est.bg }}>{est.l}</span>
                <span style={{ fontSize: 12, color: C.gris }}>ver cuenta ›</span>
              </div>
            </button>
            <div style={{ display: "flex", gap: 8, marginTop: 12 }}>
              {f.estado !== "pagado" ? (
                <button style={S.btnMini} onClick={() => setRegistrar({ dueno: f.dueno, periodo: per })}>
                  + Registrar pago
                </button>
              ) : (
                <button style={S.btnMiniGhost} onClick={() => setDetalleDueno(f.dueno)}>Ver recibo</button>
              )}
            </div>
          </div>
        );
      })}

      {/* Pasarela preparada (módulo 5) */}
      <TarjetaPasarela />

      {detalleDueno && (
        <EstadoCuenta ctx={ctx} dueno={detalleDueno}
          onRegistrar={(periodo) => { setRegistrar({ dueno: detalleDueno, periodo }); }}
          onCerrar={() => setDetalleDueno(null)} />
      )}
      {registrar && (
        <FormPago ctx={ctx} dueno={registrar.dueno} periodo={registrar.periodo}
          onCerrar={() => setRegistrar(null)} />
      )}
      {recordatorio && (
        <RecordatorioCobro dueno={recordatorio} ctx={ctx} periodo={per}
          onCerrar={() => setRecordatorio(null)} />
      )}
    </div>
  );
}

/* ---- Módulo 1: estado de cuenta detallado por dueño ---- */
function EstadoCuenta({ ctx, dueno, onRegistrar, onCerrar }) {
  const { pagos, perros } = ctx;
  const tarifa = planPorCodigo(dueno.plan)?.tarifa || 0;
  const meses = mesesRecientes(6);
  const perrosDueno = perros.filter((p) => p.dueno_id === dueno.id && p.activo !== false);

  const totalPagado = meses.reduce((s, m) => {
    const em = estadoDelMes(pagos, dueno.id, m, tarifa);
    return s + (em.estado === "pagado" ? tarifa : em.estado === "parcial" ? em.pagado : 0);
  }, 0);

  return (
    <Modal titulo="Estado de cuenta" onCerrar={onCerrar}>
      <div style={S.cuentaHero}>
        <div style={{ fontSize: 19, fontWeight: 800, color: C.carbon }}>{dueno.nombre}</div>
        <div style={{ fontSize: 13, color: C.gris }}>{dueno.torre_apto}</div>
        <div style={{ fontSize: 13, color: C.gris, marginTop: 2 }}>
          {perrosDueno.map((p) => `${p.emoji || "🐶"} ${p.nombre}`).join(" · ")}
        </div>
        <div style={{ marginTop: 10, display: "flex", gap: 16 }}>
          <div>
            <div style={{ fontSize: 11, color: C.gris }}>Plan</div>
            <div style={{ fontWeight: 700, color: C.carbon, fontSize: 14 }}>{planPorCodigo(dueno.plan)?.l}</div>
          </div>
          <div>
            <div style={{ fontSize: 11, color: C.gris }}>Pagado (6 meses)</div>
            <div style={{ fontWeight: 800, color: C.verde, fontSize: 14 }}>{fmtCOP(totalPagado)}</div>
          </div>
        </div>
      </div>

      <div style={{ fontSize: 12, fontWeight: 800, color: C.gris, textTransform: "uppercase", letterSpacing: "0.05em", margin: "6px 0 8px" }}>Historial</div>
      {meses.map((m) => {
        const em = estadoDelMes(pagos, dueno.id, m, tarifa);
        const est = estadoPagoPorC(em.estado);
        const g = em.registro;
        const metodo = g?.metodo ? METODOS.find((x) => x.c === g.metodo) : null;
        return (
          <div key={m} style={S.mesFila}>
            <div style={{ flex: 1 }}>
              <div style={{ fontWeight: 700, color: C.carbon }}>{nombreMes(m)}</div>
              <div style={{ fontSize: 11.5, color: C.gris }}>
                {g?.fecha_pago ? `${metodo?.icono || ""} ${fmtFechaCorta(g.fecha_pago)}` : "Sin registrar"}
                {em.estado === "parcial" && ` · abonó ${fmtCOP(em.pagado)}`}
              </div>
            </div>
            <span style={{ ...S.estadoBadge, color: est.color, background: est.bg, marginRight: 8 }}>{est.l}</span>
            {em.estado !== "pagado" && (
              <button style={S.mesRegBtn} onClick={() => { onCerrar(); onRegistrar(m); }}>Registrar</button>
            )}
          </div>
        );
      })}
    </Modal>
  );
}

/* ---- Módulo 2: registrar un pago ---- */
function FormPago({ ctx, dueno, periodo, onCerrar }) {
  const { pagos, guardarPago } = ctx;
  const tarifa = planPorCodigo(dueno.plan)?.tarifa || 0;
  const existente = pagos.find((g) => g.dueno_id === dueno.id && g.periodo === periodo && g.estado !== "anulado");

  const [f, setF] = useState(existente || {
    dueno_id: dueno.id,
    periodo,
    monto: tarifa,
    metodo: "efectivo",
    estado: "pagado",
    fecha_pago: hoyISO(),
  });
  const set = (k, v) => setF((s) => ({ ...s, [k]: v }));
  const parcial = Number(f.monto) < tarifa && Number(f.monto) > 0;

  const guardar = async () => {
    const estado = Number(f.monto) >= tarifa ? "pagado" : Number(f.monto) > 0 ? "parcial" : "pendiente";
    await guardarPago({ ...f, monto: Number(f.monto) || 0, estado });
    onCerrar();
  };

  const metodosVisibles = METODOS.filter((m) => !m.pasarela || PASARELA_ACTIVA);

  return (
    <Modal titulo="Registrar pago" onCerrar={onCerrar}>
      <div style={S.avisoInfo}>
        {dueno.nombre} · {nombreMes(periodo)} · plan de {fmtCOP(tarifa)}
      </div>

      <Campo label="Monto recibido (COP)">
        <input style={S.input} inputMode="numeric" value={f.monto}
          onChange={(e) => set("monto", e.target.value.replace(/[^\d]/g, ""))} placeholder={String(tarifa)} />
        <div style={{ display: "flex", gap: 8, marginTop: 8 }}>
          <button style={S.chipMonto} onClick={() => set("monto", tarifa)}>Completo {fmtCOP(tarifa)}</button>
          {parcial && <span style={{ ...S.chipMonto, background: "#FBF1DC", color: "#B07A16", border: "none" }}>Abono parcial</span>}
        </div>
      </Campo>

      <Campo label="Método">
        <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
          {metodosVisibles.map((m) => (
            <button key={m.c} onClick={() => set("metodo", m.c)}
              style={{ ...S.metodoOpcion, ...(f.metodo === m.c ? S.metodoOpcionOn : {}) }}>
              <span style={{ fontSize: 20 }}>{m.icono}</span>
              <div style={{ textAlign: "left", flex: 1 }}>
                <div style={{ fontWeight: 700, fontSize: 14 }}>{m.l}</div>
                {m.nota && <div style={{ fontSize: 11.5, color: f.metodo === m.c ? "#EAF3EE" : C.gris }}>{m.nota}</div>}
              </div>
              <span style={{ ...S.radio, ...(f.metodo === m.c ? S.radioOn : {}) }} />
            </button>
          ))}
        </div>
      </Campo>

      <Campo label="Fecha del pago">
        <input style={S.input} type="date" value={f.fecha_pago} max={hoyISO()}
          onChange={(e) => set("fecha_pago", e.target.value)} />
      </Campo>

      <button style={S.btnPrimario} onClick={guardar}>
        {parcial ? "Registrar abono" : "Registrar pago completo"}
      </button>
      {existente && (
        <button style={S.btnEliminar} onClick={async () => { await guardarPago({ ...existente, estado: "anulado" }); onCerrar(); }}>
          Anular este pago
        </button>
      )}
    </Modal>
  );
}

/* ---- Módulo 3: recordatorio de cobro cálido y paisa ---- */
function RecordatorioCobro({ dueno, ctx, periodo, onCerrar }) {
  const { perros } = ctx;
  const [copiado, setCopiado] = useState(false);
  const tarifa = planPorCodigo(dueno.plan)?.tarifa || 0;
  const perrosDueno = perros.filter((p) => p.dueno_id === dueno.id && p.activo !== false);
  const nombrePerro = perrosDueno[0]?.nombre;

  const texto = construirRecordatorio(dueno, nombrePerro, tarifa, periodo);

  const copiar = async () => {
    try {
      await navigator.clipboard.writeText(texto);
      setCopiado(true); setTimeout(() => setCopiado(false), 2000);
    } catch (e) {
      const ta = document.getElementById("record-ta");
      if (ta) { ta.select(); document.execCommand("copy"); setCopiado(true); setTimeout(() => setCopiado(false), 2000); }
    }
  };
  const waUrl = dueno.telefono
    ? `https://wa.me/${telWa(dueno.telefono)}?text=${encodeURIComponent(texto)}`
    : `https://wa.me/?text=${encodeURIComponent(texto)}`;

  return (
    <Modal titulo="Recordatorio de pago" onCerrar={onCerrar}>
      <div style={S.avisoInfo}>Mensaje para {dueno.nombre} · {nombreMes(periodo)}</div>
      <textarea id="record-ta" readOnly value={texto} style={S.reporteTa} />
      <button style={S.btnPrimario} onClick={copiar}>{copiado ? "✓ ¡Copiado!" : "📋 Copiar texto"}</button>
      <a href={waUrl} target="_blank" rel="noreferrer" style={S.btnWaFull}>
        💬 Enviar por WhatsApp{dueno.telefono ? ` a ${dueno.nombre.split(" ")[0]}` : ""}
      </a>
      {!dueno.telefono && (
        <div style={{ ...S.avisoInfo, marginTop: 12 }}>
          Este dueño no tiene teléfono guardado. El botón abre WhatsApp con el texto listo.
        </div>
      )}
    </Modal>
  );
}

function construirRecordatorio(dueno, nombrePerro, tarifa, periodo) {
  const nombre = dueno.nombre.split(" ")[0];
  const conPerro = nombrePerro ? ` a ${nombrePerro}` : "";
  return `¡Hola ${nombre}! 🐾 ¿Cómo vas?

Te escribo para recordarte con cariño el pago de los paseos de ${nombreMes(periodo)}${conPerro}: ${fmtCOP(tarifa)}.

Cuando puedas me confirmás y coordinamos. Podés pagar en efectivo o por transferencia (Nequi o Bancolombia). 💚

¡Gracias por confiarnos tu peludito!
Caninatas`;
}

/* ---- Módulo 5: pasarela preparada pero desactivada ---- */
function TarjetaPasarela() {
  return (
    <div style={S.pasarelaCard}>
      <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
        <span style={{ fontSize: 22 }}>💳</span>
        <div style={{ flex: 1 }}>
          <div style={{ fontWeight: 800, color: C.carbon, fontSize: 14.5 }}>Pagos en la app</div>
          <div style={{ fontSize: 12.5, color: C.gris }}>
            {PASARELA_ACTIVA ? "Pasarela activa" : "Próximamente · pasarela COP"}
          </div>
        </div>
        <span style={PASARELA_ACTIVA ? S.pasarelaOn : S.pasarelaOff}>
          {PASARELA_ACTIVA ? "Activa" : "Desactivada"}
        </span>
      </div>
      {!PASARELA_ACTIVA && (
        <div style={{ fontSize: 12.5, color: C.gris, marginTop: 8, lineHeight: 1.4 }}>
          Cuando quieras cobrar dentro de la app con tarjeta o PSE, se activa acá. Por ahora, los pagos se
          registran a mano (efectivo o transferencia).
        </div>
      )}
    </div>
  );
}

/* ======================================================================= */
/*                                RESUMEN                                  */
/* ======================================================================= */
function Resumen({ ctx }) {
  const { perros, duenos, pagos, paseos } = ctx;
  const per = periodoActual();
  const hoy = hoyISO();

  const perrosActivos = perros.filter((p) => p.activo !== false);
  const duenosActivos = duenos.filter((d) => d.activo !== false);

  const proyectado = duenosActivos.reduce((s, d) => s + (planPorCodigo(d.plan)?.tarifa || 0), 0);
  const cobrado = duenosActivos.reduce((s, d) => {
    const g = pagos.find((x) => x.dueno_id === d.id && x.periodo === per && x.estado === "pagado");
    return s + (g ? (planPorCodigo(d.plan)?.tarifa || 0) : 0);
  }, 0);
  const pendientes = duenosActivos.filter((d) =>
    !pagos.find((x) => x.dueno_id === d.id && x.periodo === per && x.estado === "pagado")
  );

  const paseosHoy = paseos.filter((w) => w.fecha === hoy);
  const serviciosHoy = paseosHoy.reduce((s, w) => s + w.perro_ids.length, 0);
  const capacidadPct = Math.min(100, Math.round((serviciosHoy / CAPACIDAD_DIA) * 100));
  const cobradoPct = proyectado ? Math.round((cobrado / proyectado) * 100) : 0;

  return (
    <div>
      <Header titulo="Resumen" sub={`Hoy · ${hoy}`} />

      <div style={S.gridKpi}>
        <Kpi icono="🐕" valor={perrosActivos.length} label="Perros activos" color={C.verde} />
        <Kpi icono="🏠" valor={duenosActivos.length} label="Familias" color={C.terracota} />
      </div>

      {/* Ingresos */}
      <div style={S.bloque}>
        <div style={S.bloqueTit}>Ingresos de {nombreMes(per)}</div>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "baseline", marginBottom: 6 }}>
          <span style={{ fontSize: 26, fontWeight: 800, color: C.verde }}>{fmtCOP(cobrado)}</span>
          <span style={{ color: C.gris, fontSize: 14 }}>de {fmtCOP(proyectado)} proyectado</span>
        </div>
        <Barra pct={cobradoPct} color={C.verde} />
        <div style={{ fontSize: 13, color: C.gris, marginTop: 6 }}>
          {cobradoPct}% cobrado · {pendientes.length} pendiente{pendientes.length !== 1 ? "s" : ""}
        </div>
      </div>

      {/* Capacidad */}
      <div style={S.bloque}>
        <div style={S.bloqueTit}>Capacidad de hoy</div>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "baseline", marginBottom: 6 }}>
          <span style={{ fontSize: 26, fontWeight: 800, color: capacidadPct > 80 ? C.terracota : C.verde }}>
            {serviciosHoy}<span style={{ fontSize: 16, color: C.gris }}> / {CAPACIDAD_DIA}</span>
          </span>
          <span style={{ color: C.gris, fontSize: 14 }}>servicios</span>
        </div>
        <Barra pct={capacidadPct} color={capacidadPct > 80 ? C.terracota : C.verdeClaro} />
        {capacidadPct > 80 && (
          <div style={{ fontSize: 13, color: C.terracota, marginTop: 6 }}>
            Cerca del tope. Con más demanda sostenida, es momento de pensar en un segundo paseador.
          </div>
        )}
      </div>

      {/* Pagos pendientes */}
      {pendientes.length > 0 && (
        <div style={S.bloque}>
          <div style={S.bloqueTit}>Pagos pendientes</div>
          {pendientes.map((d) => (
            <div key={d.id} style={S.filaPend}>
              <span style={{ color: C.carbon }}>{d.nombre}</span>
              <span style={{ color: C.rojo, fontWeight: 700 }}>{fmtCOP(planPorCodigo(d.plan)?.tarifa || 0)}</span>
            </div>
          ))}
        </div>
      )}

      {/* Paseos de hoy */}
      <div style={S.bloque}>
        <div style={S.bloqueTit}>Paseos de hoy</div>
        {paseosHoy.length === 0 ? (
          <div style={{ color: C.gris, fontSize: 14 }}>Todavía no hay paseos registrados hoy.</div>
        ) : (
          paseosHoy.map((w) => {
            const ronda = RONDAS.find((r) => r.c === w.ronda);
            return (
              <div key={w.id} style={S.filaPend}>
                <span style={{ color: C.carbon }}>{ronda?.l.split(" · ")[0] || w.ronda}</span>
                <span style={{ color: C.gris }}>{w.perro_ids.length} perro{w.perro_ids.length !== 1 ? "s" : ""}</span>
              </div>
            );
          })
        )}
      </div>

      <div style={{ height: 10 }} />
    </div>
  );
}

/* ======================================================================= */
/*                          COMPONENTES BASE                              */
/* ======================================================================= */
function Shell({ children }) {
  return (
    <div style={S.shell}>
      <div style={S.frame}>{children}</div>
    </div>
  );
}

function Header({ titulo, sub }) {
  return (
    <div style={S.header}>
      <img src={LOGO_CANINATAS} alt="Caninatas" style={S.logoImg} />
      <div>
        <div style={S.headerTit}>{titulo}</div>
        {sub && <div style={S.headerSub}>{sub}</div>}
      </div>
    </div>
  );
}

function BarraPestanas({ tab, setTab }) {
  const items = [
    { c: "manada", l: "Manada", i: "🐕" },
    { c: "agenda", l: "Agenda", i: "📅" },
    { c: "paseos", l: "Bitácora", i: "🚶" },
    { c: "pagos", l: "Pagos", i: "💵" },
    { c: "resumen", l: "Resumen", i: "📊" },
  ];
  return (
    <div style={S.tabbar}>
      {items.map((it) => (
        <button key={it.c} onClick={() => setTab(it.c)}
          style={{ ...S.tabItem, ...(tab === it.c ? S.tabItemOn : {}) }}>
          <span style={{ fontSize: 20, filter: tab === it.c ? "none" : "grayscale(0.4)" }}>{it.i}</span>
          <span style={{ fontSize: 10, fontWeight: tab === it.c ? 700 : 500 }}>{it.l}</span>
        </button>
      ))}
    </div>
  );
}

function Modal({ titulo, onCerrar, children }) {
  return (
    <div style={S.overlay} onClick={onCerrar}>
      <div style={S.modal} onClick={(e) => e.stopPropagation()}>
        <div style={S.modalHead}>
          <span style={S.modalTit}>{titulo}</span>
          <button style={S.cerrar} onClick={onCerrar}>✕</button>
        </div>
        <div style={S.modalBody}>{children}</div>
      </div>
    </div>
  );
}

function Campo({ label, error, obligatorio, children }) {
  return (
    <div style={{ marginBottom: 14 }}>
      <label style={S.label}>
        {label}{obligatorio && <span style={{ color: C.terracota }}> *</span>}
      </label>
      {children}
      {error && <div style={S.errorTxt}>{error}</div>}
    </div>
  );
}

function Fila({ children }) {
  return <div style={{ display: "flex", gap: 10 }}>{React.Children.map(children, (c) => <div style={{ flex: 1 }}>{c}</div>)}</div>;
}

function Segmentado({ ops, valor, onChange }) {
  return (
    <div style={{ display: "flex", flexWrap: "wrap", gap: 6 }}>
      {ops.map((o) => (
        <button key={o.c} onClick={() => onChange(o.c)}
          style={{ ...S.segPill, ...(valor === o.c ? S.segPillOn : {}) }}>{o.l}</button>
      ))}
    </div>
  );
}

function Tag({ children, color, dark }) {
  return (
    <span style={{
      ...S.tag,
      background: dark ? color : color + "22",
      color: dark ? C.carbon : color,
      border: `1px solid ${color}${dark ? "" : "44"}`,
    }}>{children}</span>
  );
}

function Kpi({ icono, valor, label, color }) {
  return (
    <div style={S.kpi}>
      <div style={{ fontSize: 24 }}>{icono}</div>
      <div style={{ fontSize: 28, fontWeight: 800, color }}>{valor}</div>
      <div style={{ fontSize: 12, color: C.gris }}>{label}</div>
    </div>
  );
}

function Barra({ pct, color }) {
  return (
    <div style={S.barraTrack}>
      <div style={{ ...S.barraFill, width: `${pct}%`, background: color }} />
    </div>
  );
}

function Vacio({ icono, titulo, texto }) {
  return (
    <div style={S.vacio}>
      <div style={{ fontSize: 44, marginBottom: 8 }}>{icono}</div>
      <div style={{ fontWeight: 700, color: C.carbon, marginBottom: 4 }}>{titulo}</div>
      <div style={{ color: C.gris, fontSize: 14, lineHeight: 1.4 }}>{texto}</div>
    </div>
  );
}

